import 'dart:ui' as ui;

import 'package:flutter/services.dart';

/// Decoded icon images (generated by tool/generate_icons_test.dart) for
/// painting inside the HUD.
class GameIcons {
  static const names = ['slash', 'shuriken', 'jump', 'smoke', 'crouch', 'pause'];
  static final Map<String, ui.Image> images = {};
  static Future<void>? _loading;

  static Future<void> load() => _loading ??= _load();

  static Future<void> _load() async {
    for (final n in names) {
      try {
        final data = await rootBundle.load('assets/icons/$n.png');
        final codec = await ui.instantiateImageCodec(data.buffer.asUint8List());
        images[n] = (await codec.getNextFrame()).image;
      } catch (_) {
        // Missing asset: the HUD falls back to a text glyph.
      }
    }
  }

  static String flagAsset(String lang) => 'assets/icons/flag_$lang.png';
}
